input.command:
mkdir -p src/inngest src/app/api/inngest && cat > src/inngest/client.ts <<'EOF'
import { Inngest } from "inngest";

// Reads INNGEST_EVENT_KEY / INNGEST_SIGNING_KEY from the environment.
export const inngest = new Inngest({ id: "notely" });
EOF
cat > src/inngest/functions.ts <<'EOF'
import { inngest } from "./client";

export const USER_CREATED_EVENT = "notely/user.created";
export const REMINDER_DELAY_MS = 10 * 60 * 1000;

export type UserCreatedData = { userId: string; email: string; name: string };

// The event is sent with a `ts` 10 minutes in the future, so this runs then.
// Inngest retries a failed run with backoff, up to `retries` extra attempts.
export const userReminder = inngest.createFunction(
  { id: "user-reminder", retries: 5, triggers: [{ event: USER_CREATED_EVENT }] },
  async ({ event, step }) => {
    const { userId, email, name } = event.data as UserCreatedData;
    await step.run("log-reminder", () => {
      console.log(`[reminder] ${name} <${email}> (user ${userId}) signed up 10 minutes ago`);
    });
  },
);
EOF
cat > src/app/api/inngest/route.ts <<'EOF'
import { serve } from "inngest/next";
import { inngest } from "@/inngest/client";
import { userReminder } from "@/inngest/functions";

export const { GET, POST, PUT } = serve({ client: inngest, functions: [userReminder] });
EOF
cat >> src/lib/users.ts <<'EOF'

export async function createUser(input: { email: string; name: string }): Promise<User> {
  const user: User = {
    id: String(users.length + 1),
    email: input.email,
    name: input.name,
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);

  // Schedule the reminder; the user is already created, so a scheduling failure must not undo it.
  try {
    await inngest.send({
      id: `user-reminder-${user.id}`, // idempotency key
      name: USER_CREATED_EVENT,
      data: { userId: user.id, email: user.email, name: user.name } satisfies UserCreatedData,
      ts: Date.now() + REMINDER_DELAY_MS,
    });
  } catch (err) {
    console.error(`Failed to schedule reminder for user ${user.id}`, err);
  }
  return user;
}
EOF
sed -i '' '1i\
import { inngest } from "@/inngest/client";\
import { REMINDER_DELAY_MS, USER_CREATED_EVENT, type UserCreatedData } from "@/inngest/functions";\

' src/lib/users.ts
cat > .env.example <<'EOF'
# Inngest (https://app.inngest.com) — placeholders, replace with real values
INNGEST_EVENT_KEY=placeholder-event-key
INNGEST_SIGNING_KEY=signkey-prod-placeholder
# Local dev only: run `npx inngest-cli@latest dev` and set INNGEST_DEV=1
# INNGEST_DEV=1
EOF
printf '!.env.example\n' >> .gitignore
npx tsc --noEmit 2>&1 | head; npm run lint 2>&1 | tail -8

